SELECT
  e.module_code,
  e.action_name,
  e.permission_code,
  pm.module_id IS NULL AS module_missing,
  (SELECT COUNT(*) FROM permission_actions pa2
     JOIN permission_modules pm2 ON pm2.module_id = pa2.module_id
     WHERE pm2.module_code = e.module_code AND pa2.action_name = e.action_name) AS action_match_count
FROM expected e
LEFT JOIN permission_modules pm ON pm.module_code = e.module_code
LEFT JOIN permission_actions pa ON pa.module_id = pm.module_id AND pa.action_name = e.action_name
WHERE pa.action_id IS NULL
ORDER BY e.module_code, e.action_name;
